// ── Inject baby photo as base64 ──
const b64 =
  "";
const src = "data:image/png;base64," + b64;
document
  .querySelectorAll('img[src="BABY_IMAGE_PLACEHOLDER"]')
  .forEach((img) => (img.src = src));

// ── Generate sparkle background ──
const bg = document.getElementById("sparkleBg");
const colors = [
  "#f9d6df",
  "#f0aec0",
  "#e8d5a3",
  "#fce4ec",
  "#fff0f5",
  "#f0e6d8",
];
const shapes = [
  // circle
  () => {
    const d = document.createElement("div");
    d.className = "sparkle";
    return d;
  },
];

for (let i = 0; i < 30; i++) {
  const el = document.createElement("div");
  el.className = "sparkle";
  const size = 6 + Math.random() * 16;
  el.style.cssText = `
    width:${size}px; height:${size}px;
    left:${Math.random() * 100}%;
    background:${colors[Math.floor(Math.random() * colors.length)]};
    --dur:${7 + Math.random() * 10}s;
    --delay:${Math.random() * 8}s;
    border-radius:${Math.random() > 0.5 ? "50%" : "4px"};
    opacity:0;
  `;
  bg.appendChild(el);
}

// ── Star sparkles ──
for (let i = 0; i < 15; i++) {
  const el = document.createElement("div");
  el.innerHTML = ["✦", "✧", "⋆", "·"][Math.floor(Math.random() * 4)];
  el.style.cssText = `
    position:absolute;
    font-size:${8 + Math.random() * 14}px;
    color:${colors[Math.floor(Math.random() * colors.length)]};
    left:${Math.random() * 100}%;
    opacity:0;
    animation:floatUp ${8 + Math.random() * 10}s ease-in-out ${Math.random() * 8}s infinite;
    pointer-events:none;
  `;
  bg.appendChild(el);
}
